{"code": "import os
import json
from datetime import datetime, timedelta

sessions_dir = "/Users/ktoclaw/.hermes/sessions"
cutoff = datetime.now() - timedelta(days=7)  # May 26, 2026
print(f"Cutoff: {cutoff.date()}")

old_files = []
recent_files = []

for fname in os.listdir(sessions_dir):
    if not fname.endswith('.json') or fname == 'sessions.json':
        continue
    fpath = os.path.join(sessions_dir, fname)
    mtime = datetime.fromtimestamp(os.path.getmtime(fpath))
    if mtime < cutoff:
        old_files.append((fname, mtime.date()))
    else:
        recent_files.append((fname, mtime.date()))

print(f"\nOLD (>7 days, to delete): {len(old_files)}")
for f, d in sorted(old_files):
    print(f"  {d}  {f}")

print(f"\nRECENT (<=7 days, keep): {len(recent_files)}")
for f, d in sorted(recent_files):
    print(f"  {d}  {f}")"}
